insert into public.sources (id, title, publisher, url, kind, official, published_on, retrieved_on, reference, notes) values
  ('sanral-tariffs-2026-poster', 'New toll tariffs from 1 March 2026 (tariff poster)', 'South African National Roads Agency SOC Ltd (SANRAL)', 'https://www.nra.co.za/uploads/17/SANRAL%20Toll%20Tariff%202026%20A3%20Poster%20v2.pdf', 'agency_publication', true, '2026-02-05', '2026-10-23', 'Government Gazette Nos. 54087 and 54088 (5 February 2026)', 'Opened and read in full on 23 October 2026: 73 tariff rows for all SANRAL, N3TC, TRAC and Bakwena conventional plazas, colour-coded by operator. Tariffs include VAT. The poster states it does not replace Government Gazette Nos. 54087 and 54088 (5 February 2026); those could not be retrieved, because gpwonline serves them through SharePoint.'),
  ('sanews-2026-toll-increase', 'SANRAL increases toll tariffs', 'SAnews (Government Communication and Information System)', 'https://www.sanews.gov.za/south-africa/sanral-increases-toll-tariffs', 'news', true, '2026-02-05', '2026-10-21', null, 'Reports the 3.12% CPI-linked adjustment effective 1 March 2026.'),
  ('sanral-tariffs-2025-booklet', '1 March 2025 toll tariff adjustment booklet', 'South African National Roads Agency SOC Ltd (SANRAL)', 'https://www.nra.co.za/uploads/17/SANRAL%20Toll%20Adjustment%20Booklet%20-%20Online.pdf', 'agency_publication', true, '2025-02-07', '2026-10-21', 'Government Gazette No. 52073 (7 February 2025)', '4.84% CPI-linked adjustment. Defines classes by axle count. Extract text was partly garbled. Superseded as a reference by the Gazette itself (gazette-52073-2025).'),
  ('satrucker-2025', 'New Toll Fees Effective 1 March 2025', 'SA Trucker', 'https://satrucker.co.za/new-toll-fees-effective-1-march-2025/', 'secondary_compilation', false, null, '2026-10-21', null, 'Third-party table of the 2025 schedule. Used only where it agrees with another source.'),
  ('n3tc-toll-tariffs', 'Toll Tariffs', 'N3 Toll Concession (N3TC)', 'https://www.n3tc.co.za/toll-tariffs/', 'operator_website', true, null, '2026-10-21', null, 'Could not be opened on 23 October 2026: the site''s certificate chains to Let''s Encrypt''s new ISRG Root YR, which the build environment does not trust. The figures seen earlier in a search index equal the 2025 values in Government Gazette No. 52072, so that snapshot showed the 2025 schedule. The 2026 N3 values follow the SANRAL 2026 poster.'),
  ('foresight-n3-2026', 'N3 Toll Fees (tariffs effective 1 March 2026)', 'Foresight Publications', 'https://www.foresightpublications.co.za/TollroadsN3.html', 'secondary_compilation', false, null, '2026-10-21', null, 'Third-party table. Class 1 values match the SANRAL 2026 poster.'),
  ('trac-toll-fees', 'Toll plazas & toll fees', 'Trans African Concessions (TRAC N4)', 'https://tracn4.co.za/toll-plazas-toll-fees/', 'operator_website', true, null, '2026-10-23', null, 'Effective from 1 March 2026. Opened on 23 October 2026: lists eight South African plazas (including Cullinan Ramp); every value matches the SANRAL 2026 poster. Middelburg now shows a single Class 3 amount (R277).'),
  ('bakwena-tolls-and-tariffs', 'Tolls and Tariffs', 'Bakwena Platinum Corridor Concessionaire', 'https://www.bakwena.co.za/tolls-and-tariffs/', 'operator_website', true, null, '2026-10-23', null, 'Tariffs valid 1 March 2026 to 28 February 2027, VAT inclusive. Opened on 23 October 2026: lists every Bakwena N1 and N4 plaza, including Murrayhill, Hammanskraal, Maubane, Buffelspoort Ramps and ''Doornpoort Ramps''. Every value matches the SANRAL 2026 poster.'),
  ('joburgetc-2026', 'Sanral Toll Fees 2026: New N1, N2, N3, N4 Prices: Route Costs', 'Joburg ETC', 'https://www.joburgetc.com/news/sanral-toll-fee-increase-2026-south-africa/', 'secondary_compilation', false, null, '2026-10-21', null, null),
  ('joburgetc-2025', 'Toll Fee Increases for 2025: What You''ll Pay on Major Routes', 'Joburg ETC', 'https://www.joburgetc.com/news/411/toll-fee-increases-2025/', 'secondary_compilation', false, null, '2026-10-21', null, null),
  ('sapeople-2025', 'Toll fee hikes 2025: What it will cost to drive on SA roads', 'SA People', 'https://www.sapeople.com/news/toll-fee-hikes-2025-what-it-will-cost-to-drive-on-sa-roads/', 'news', false, null, '2026-10-21', null, null),
  ('tripcost-tolls', 'South African toll plazas: 2026 tariffs by road', 'tripcost.co.za', 'https://tripcost.co.za/tolls/', 'secondary_compilation', false, null, '2026-10-21', null, 'Third-party site. Some plaza pages give coordinates and are internally inconsistent; used only as a corroborating signal.'),
  ('tollguru-za', 'South Africa Toll Roads Complete Guide', 'TollGuru', 'https://tollguru.com/south-africa-tolls-highways-e-tolls', 'secondary_compilation', false, null, '2026-10-21', null, 'Third-party guide; describes several plaza locations inconsistently.'),
  ('topauto-2026', 'Toll price hikes for all major roads in South Africa', 'TopAuto', 'https://topauto.co.za/news/143061/toll-price-hikes-for-all-major-roads-in-south-africa/', 'news', false, null, '2026-10-21', null, null),
  ('iol-2026-routes', 'Here''s how much you''ll pay in toll fees on South Africa''s major routes after Sanral''s 2026 increase', 'IOL', 'https://iol.co.za/motoring/industry-news/2026-03-11-heres-how-much-youll-pay-in-toll-fees-on-south-africas-major-routes-after-sanrals-2026-increase/', 'news', false, '2026-03-11', '2026-10-21', null, 'Lists the five N3 plazas between Johannesburg and Durban and the Tsitsikamma plaza as the only N2 Garden Route mainline toll.'),
  ('chapmans-peak-gazette-2026', 'Provincial Notice 138/2026 — levying and collection of tolls, Chapman''s Peak Drive', 'Western Cape Government (Provincial Gazette Extraordinary 9246)', 'https://www.chapmanspeakdrive.co.za/images/assets_downloads/Government_Gazette_2026_06.pdf', 'government_gazette', true, '2026-06-05', '2026-10-21', 'Provincial Notice 138/2026; repeals Provincial Notice 61/2025', 'Tolls effective 1 July 2026 under the Western Cape Toll Roads Act, 1999. Table text was partly garbled in the extract.'),
  ('chapmans-peak-website', 'Chapman''s Peak Drive', 'Chapman''s Peak Drive', 'https://www.chapmanspeakdrive.co.za/', 'operator_website', true, null, '2026-10-21', null, null),
  ('sanral-sst-locations', 'Self-service terminal locations', 'South African National Roads Agency SOC Ltd (SANRAL)', 'https://www.sanral.co.za/e-toll/portal/publicpages/SST_Locations.pdf', 'agency_publication', true, null, '2026-10-21', null, 'Lists terminal positions, many at toll plazas. Not every terminal is at a plaza (at least one is at a petroport), so positions are treated as approximate.'),
  ('sanral-toll-plaza-list', 'Toll plaza list', 'South African National Roads Agency SOC Ltd (SANRAL)', 'https://www.sanral.co.za/e-toll/portal/publicpages/Toll_Plaza.pdf', 'agency_publication', true, null, '2026-10-21', null, 'Groups plazas by section, e.g. N1 South: Grasmere, Vaal (Kroonvaal), Verkeerdevlei; N1 Great North: Kranskop, Nyl, Capricorn, Baobab.'),
  ('wikipedia-n1', 'N1 (South Africa)', 'Wikipedia', 'https://en.wikipedia.org/wiki/N1_(South_Africa)', 'map_data', false, null, '2026-10-21', null, 'Coordinates for several N1 plazas (read via Wikiwand mirror).'),
  ('wikipedia-n3', 'N3 (South Africa)', 'Wikipedia', 'https://en.wikipedia.org/wiki/N3_(South_Africa)', 'map_data', false, null, '2026-10-21', null, 'De Hoek is the last plaza before Heidelberg northbound; Mariannhill plaza is on the Mariannhill Toll Road section outside the N3TC concession.'),
  ('southafricaexplorer-toll-gates', 'South African toll gates and locations map', 'South Africa Explorer', 'http://southafricaexplorer.co.za/articles/maps/map-toll-gates.html', 'map_data', false, null, '2026-10-21', null, 'Undated third-party GPS list with several rows demonstrably misaligned. Used only where another source supports the position.'),
  ('randtools-de-hoek', 'De Hoek Toll Plaza — fees, location & map', 'Rand Tools', 'https://randtools.co.za/drive/toll-gate/de-hoek', 'secondary_compilation', false, null, '2026-10-21', null, 'Describes De Hoek as about 65 km south of Johannesburg, between Heidelberg and Villiers.'),
  ('businesstech-toll-payments', 'Big payment changes for N3 and N4 tolls in South Africa this holiday season', 'BusinessTech', 'https://businesstech.co.za/news/?p=800767', 'news', false, null, '2026-10-21', null, null),
  ('pretorianews-tap-to-pay', 'South Africa to roll out tap-to-pay at toll plazas by end of 2025', 'Pretoria News', 'https://pretorianews.co.za/business/2025-09-17-south-africa-to-roll-out-tap-to-pay-at-toll-plazas-by-end-of-2025/', 'news', false, '2025-09-17', '2026-10-21', null, 'SANRAL plazas replace magstripe cards with contactless EMV from 1 December 2025; N3TC and TRAC introduced tap-and-go in 2024; Bakwena targeted Q4 2025. Cash and SANRAL tags remain accepted.'),
  ('sanral-etoll-end-information-pack', 'Government ends e-tolls in Gauteng — information pack (10 April 2024)', 'South African National Roads Agency SOC Ltd (SANRAL)', 'https://www.nra.co.za/uploads/184/FAQ_Infromation%20Pack%20-%2010April24.pdf', 'agency_publication', true, '2024-04-10', '2026-10-21', null, null),
  ('engineeringnews-etoll-debt-2026', 'Govt writes off e-toll debt, but those who paid will not receive refunds', 'Engineering News', 'https://www.engineeringnews.co.za/print-version/govt-writes-off-e-toll-debt-but-those-who-paid-will-not-receive-refunds-2026-06-08', 'news', false, '2026-06-08', '2026-10-21', null, null),
  ('foresight-n2-2026', 'N2 Toll Fees (tariffs effective 1 March 2026)', 'Foresight Publications', 'https://www.foresightpublications.co.za/TollroadsN2.html', 'secondary_compilation', false, null, '2026-10-21', null, 'Third-party table. Agrees with Joburg ETC for the South Coast ramps and with TollGuru for oThongathi.'),
  ('foresight-n17-2026', 'N17 Toll Fees (tariffs effective 1 March 2026)', 'Foresight Publications', 'https://www.foresightpublications.co.za/TollroadsN17.html', 'secondary_compilation', false, null, '2026-10-21', null, 'Third-party table. Leandra, Trichardt and Ermelo values agree with the 2025 values plus 3.12%.'),
  ('limpopo-chronicle-2026', 'Toll fees increase 2026 – how much you''ll pay on N1 Limpopo', 'Limpopo Chronicle', 'https://www.limpopochronicle.co.za/2026/02/21/toll-fees-increase-2026-how-much-youll-pay-on-n1-limpopo/', 'news', false, '2026-02-21', '2026-10-21', null, null),
  ('wikipedia-platinum-highway', 'Platinum Highway', 'Wikipedia', 'https://en.wikipedia.org/wiki/Platinum_Highway', 'map_data', false, null, '2026-10-21', null, 'Four toll plazas on the N4 Platinum Highway: at the N1 interchange (Doornpoort), east of Brits, east of Rustenburg (Marikana) and west of Swartruggens.'),
  ('randtools-n4', 'N4 toll gates 2026', 'Rand Tools', 'https://randtools.co.za/drive/road/n4', 'secondary_compilation', false, null, '2026-10-21', null, 'Pretoria to Mbombela passes Diamond Hill, Middelburg and Machado, in that order.'),
  ('randtools-pta-polokwane', 'Polokwane to Pretoria: toll gates', 'Rand Tools', 'https://randtools.co.za/drive/limpopo-to-gauteng', 'secondary_compilation', false, null, '2026-10-21', null, 'Lists Pumulani, Carousel, Kranskop and Nyl as the four mainline plazas between Pretoria and Polokwane.'),
  ('fncalculator-2025', 'Toll Gate Fees Calculator South Africa 2025', 'fncalculator.co.za', 'https://fncalculator.co.za/toll-calculator-south-africa', 'secondary_compilation', false, null, '2026-10-21', null, 'Matches the SA Trucker 2025 table for N17 plazas.'),
  ('gazette-52073-2025', 'Huguenot, Vaal River, Great North, Tsitsikamma, South Coast, North Coast, Mariannhill, Magalies, N17 and R30/R730/R34 Toll Roads: amounts of toll from 1 March 2025', 'Government Gazette (Department of Transport)', 'https://www.nra.co.za/uploads/17/20250207%20Goverment%20Gazette%20Vol716%20No52073%207-2%20Transport%20-%20SANRAL%20CTROM%20Toll%20Tariffs%2020250301_0.pdf', 'government_gazette', true, '2025-02-07', '2026-10-23', 'Government Gazette Vol. 716 No. 52073, Notice 5853 (7 February 2025)', 'Copy hosted by SANRAL. Scanned pages: values were read from the page images on 23 October 2026.'),
  ('gazette-52072-2025', 'National Routes 1 and 4 Platinum Toll Road and National Route 3 Cedara to Heidelberg Toll Road: amounts of toll from 1 March 2025', 'Government Gazette (Department of Transport)', 'https://www.nra.co.za/uploads/17/20250207%20Government%20gazette%20Vol716%20No52072%207-2%20Transport%20-%20SANRAL%20Concessionairs%20Toll%20Tariffs%2020250301.pdf', 'government_gazette', true, '2025-02-07', '2026-10-23', 'Government Gazette Vol. 716 No. 52072, Notice 5852 (7 February 2025)', 'Copy hosted by SANRAL. Scanned pages: values were read from the page images on 23 October 2026.');
insert into public.operators (id, name, short_name, kind, website, phone, email, contact_status, payment_methods, payment_status, payment_source_ids, payment_notes, source_ids, notes) values
  ('sanral', 'South African National Roads Agency SOC Ltd', 'SANRAL', 'national_agency', 'https://www.nra.co.za/', null, null, 'unverified', array['cash', 'contactless_card', 'e_tag']::text[], 'unverified', array['pretorianews-tap-to-pay', 'businesstech-toll-payments']::text[], 'News reports: magstripe cards replaced by contactless (EMV) bank cards and mobile wallets from 1 December 2025. American Express, Diners Club and RCS cards are not accepted. Cash and SANRAL tags remain accepted.', array['sanral-tariffs-2026-poster', 'sanral-toll-plaza-list']::text[], null),
  ('n3tc', 'N3 Toll Concession', 'N3TC', 'concessionaire', 'https://www.n3tc.co.za/', null, null, 'unverified', array['cash', 'contactless_card', 'e_tag']::text[], 'unverified', array['pretorianews-tap-to-pay', 'businesstech-toll-payments']::text[], 'News reports: tap-and-go card payments introduced in 2024. Cash and SANRAL tags reported as accepted.', array['n3tc-toll-tariffs']::text[], 'Concession for the N3 between Cedara (KwaZulu-Natal) and Heidelberg (Gauteng). Mariannhill plaza is a SANRAL plaza outside the concession.'),
  ('trac', 'Trans African Concessions', 'TRAC', 'concessionaire', 'https://tracn4.co.za/', null, null, 'unverified', array['cash', 'contactless_card', 'e_tag']::text[], 'unverified', array['pretorianews-tap-to-pay', 'businesstech-toll-payments']::text[], 'News reports: tap-and-go card payments introduced in 2024. Cash and SANRAL tags reported as accepted.', array['trac-toll-fees']::text[], 'N4 Maputo Development Corridor (South African section).'),
  ('bakwena', 'Bakwena Platinum Corridor Concessionaire', 'Bakwena', 'concessionaire', 'https://www.bakwena.co.za/', null, null, 'unverified', array['cash', 'e_tag']::text[], 'unverified', array['pretorianews-tap-to-pay']::text[], 'News reports: contactless card payments targeted for Q4 2025 — not confirmed as live. Cash and SANRAL tags reported as accepted.', array['bakwena-tolls-and-tariffs']::text[], 'N1 (Pretoria–Bela-Bela section) and N4 Platinum Corridor.'),
  ('chapmans-peak', 'Chapman''s Peak Drive toll concession', 'Chapman''s Peak Drive', 'provincial_concession', 'https://www.chapmanspeakdrive.co.za/', null, null, 'unverified', null, null, '{}'::text[], null, array['chapmans-peak-website', 'chapmans-peak-gazette-2026']::text[], 'Tolls levied under the Western Cape Toll Roads Act, 1999. The concessionaire''s registered name has not been confirmed. Payment methods not yet researched.');
