  ('sanral-n3-mariannhill', 'N3 Mariannhill', array['N3']::text[], 'sanral', array['KZN']::public.province_code[], 'Short SANRAL toll section on the N3 west of Durban, outside the N3TC concession.', array['sanral-tariffs-2026-poster', 'wikipedia-n3']::text[]),
  ('sanral-n17', 'N17', array['N17']::text[], 'sanral', array['GP', 'MP']::public.province_code[], null, array['sanral-tariffs-2026-poster', 'sanral-sst-locations']::text[]),
  ('n3tc-n3', 'N3 Toll Route', array['N3']::text[], 'n3tc', array['GP', 'FS', 'KZN']::public.province_code[], 'N3 between Heidelberg and Cedara, operated by N3TC.', array['n3tc-toll-tariffs']::text[]),
  ('trac-n4', 'N4 Maputo Corridor', array['N4']::text[], 'trac', array['GP', 'MP']::public.province_code[], 'N4 east of Pretoria to the Mozambique border, operated by TRAC.', array['trac-toll-fees']::text[]),
  ('bakwena-n1', 'N1 Platinum Corridor', array['N1']::text[], 'bakwena', array['GP', 'NW', 'LP']::public.province_code[], 'Bakwena''s N1 section north of Pretoria.', array['bakwena-tolls-and-tariffs']::text[]),
  ('bakwena-n4', 'N4 Platinum Corridor', array['N4']::text[], 'bakwena', array['GP', 'NW']::public.province_code[], 'Bakwena''s N4 section west of Pretoria towards Botswana.', array['bakwena-tolls-and-tariffs']::text[]),
  ('chapmans-peak-drive', 'Chapman''s Peak Drive', array['M6']::text[], 'chapmans-peak', array['WC']::public.province_code[], 'Scenic toll road between Hout Bay and Noordhoek, Cape Town.', array['chapmans-peak-gazette-2026']::text[]),
  ('sanral-n4-magalies', 'N4 Magalies', array['N4']::text[], 'sanral', array['GP', 'NW']::public.province_code[], 'SANRAL toll road on the N4 west of Pretoria (Pelindaba and Quagga plazas).', array['sanral-tariffs-2026-poster', 'gazette-52073-2025']::text[]),
  ('sanral-r30', 'R30/R730/R34', array['R30']::text[], 'sanral', array['FS']::public.province_code[], 'SANRAL toll road in the Free State (Brandfort plaza).', array['sanral-tariffs-2026-poster', 'gazette-52073-2025']::text[]);
