  ('za-standard', 'class3', 'Class 3', 'Large heavy (3–4 axles)', 'Heavy vehicles with three or four axles.', 3),
  ('za-standard', 'class4', 'Class 4', 'Extra-large heavy (5+ axles)', 'Heavy vehicles with five or more axles.', 4),
  ('chapmans-peak', 'cp-motorcycle', 'Motorcycle', 'Motorcycles, tricycles and quadbikes', 'Class 1 motorcycles, tricycles and quadbikes (standard toll).', 1),
