insert into public.plazas (id, name, toll_road_id, operator_id, route, type, province, locality, carriageway, lat, lng, location_precision, location_source_ids, location_notes, status, class_scheme_id, source_ids, aliases, notes, publication_status) values
  ('n1-huguenot', 'Huguenot', 'sanral-n1-huguenot', 'sanral', 'N1', 'mainline', 'WC', 'Huguenot Tunnel, between Paarl and Worcester', null, -33.7428, 19.0197, 'approximate', array['wikipedia-n1', 'sanral-sst-locations']::text[], 'From Wikipedia''s N1 article; SANRAL''s terminal list places the plaza at Paarl. One aggregator places it about 8 km further east.', 'active', 'za-standard', array['sanral-tariffs-2026-poster']::text[], array['Huguenot Tunnel']::text[], array['Drivers using Du Toitskloof Pass instead of the Huguenot Tunnel do not pass this plaza.']::text[], 'published'),
  ('n1-grasmere', 'Grasmere', 'sanral-n1-south', 'sanral', 'N1', 'mainline', 'GP', 'N1 south of Johannesburg', null, -26.4114, 27.8842, 'approximate', array['wikipedia-n1', 'tripcost-tolls']::text[], 'Two sources agree within about 50 m.', 'active', 'za-standard', array['sanral-tariffs-2026-poster', 'sanral-toll-plaza-list']::text[], '{}'::text[], '{}'::text[], 'published'),
  ('n1-grasmere-ramp-north', 'Grasmere North Ramp', 'sanral-n1-south', 'sanral', 'N1', 'ramp', 'GP', null, null, null, null, null, '{}'::text[], null, 'active', 'za-standard', array['sanral-tariffs-2026-poster']::text[], '{}'::text[], array['Ramp plaza: charged only when your route uses this interchange.']::text[], 'published'),
  ('n1-grasmere-ramp-south', 'Grasmere South Ramp', 'sanral-n1-south', 'sanral', 'N1', 'ramp', 'GP', null, null, null, null, null, '{}'::text[], null, 'active', 'za-standard', array['sanral-tariffs-2026-poster']::text[], '{}'::text[], array['Ramp plaza: charged only when your route uses this interchange.']::text[], 'published'),
  ('n1-vaal', 'Vaal', 'sanral-n1-south', 'sanral', 'N1', 'mainline', 'FS', 'Kroonvaal section, south of the Vaal River', null, -26.8564, 27.6353, 'approximate', array['wikipedia-n1']::text[], 'Single source (Wikipedia).', 'active', 'za-standard', array['sanral-tariffs-2026-poster', 'sanral-toll-plaza-list']::text[], array['Kroonvaal']::text[], '{}'::text[], 'published'),
