insert into public.journeys (id, name, origin_label, origin_query, destination_label, destination_query, via, description, sequence_status, sequence_verified_on, sequence_verified_by, limitations, source_ids, publication_status) values
  ('jhb-dbn-n3', 'Johannesburg → Durban', 'Johannesburg', 'Johannesburg, South Africa', 'Durban', 'Durban, South Africa', 'N3', 'N3 mainline from Gauteng to Durban: four N3TC plazas and SANRAL''s Mariannhill plaza.', 'unverified', null, null, array['Assumes you stay on the N3 mainline the whole way.', 'Ramp plazas (Tugela East, Bergville, Treverton, Mooi South) apply only if you use those interchanges. Add them with “Choose plazas”.']::text[], array['iol-2026-routes', 'wikipedia-n3', 'foresight-n3-2026']::text[], 'published'),
  ('jhb-cpt-n1', 'Johannesburg → Cape Town', 'Johannesburg', 'Johannesburg, South Africa', 'Cape Town', 'Cape Town, South Africa', 'N1', 'N1 south through the Free State and the Huguenot Tunnel.', 'unverified', null, null, array['Grasmere ramp plazas apply only if you join or leave the N1 at those ramps.', 'Assumes the N1 the whole way; the N12 alternative is not covered.']::text[], array['sanral-toll-plaza-list', 'wikipedia-n1']::text[], 'published'),
  ('pta-polokwane-n1', 'Pretoria → Polokwane', 'Pretoria', 'Pretoria, South Africa', 'Polokwane', 'Polokwane, South Africa', 'N1', 'N1 north through Bakwena''s and SANRAL''s plazas.', 'unverified', null, null, array['Assumes you join the N1 south of the Pumulani plaza. Pretoria ramp plazas (Stormvoël, Zambesi, Wallmannsthal) depend on where you join.', 'Ramp plazas at Kranskop and Nyl apply only if you use those interchanges.', 'The position of the Sebetiela plaza relative to this route has not been confirmed.']::text[], array['sanral-toll-plaza-list', 'bakwena-tolls-and-tariffs', 'randtools-pta-polokwane']::text[], 'published'),
  ('polokwane-beitbridge-n1', 'Polokwane → Beitbridge', 'Polokwane', 'Polokwane, South Africa', 'Beitbridge border', 'Beitbridge Border Post, South Africa', 'N1', 'N1 north from Polokwane to the Zimbabwe border.', 'unverified', null, null, '{}'::text[], array['sanral-toll-plaza-list']::text[], 'published'),
  ('pta-mbombela-n4', 'Pretoria → Mbombela', 'Pretoria', 'Pretoria, South Africa', 'Mbombela (Nelspruit)', 'Mbombela, South Africa', 'N4', 'N4 east through TRAC''s three mainline plazas.', 'unverified', null, null, array['Ramp plazas (Donkerhoek, Valtaki, Ekandustria) apply depending on where you join or leave the N4. Add them with “Choose plazas”.']::text[], array['trac-toll-fees', 'randtools-n4']::text[], 'published'),
  ('plett-gqeberha-n2', 'Plettenberg Bay → Gqeberha', 'Plettenberg Bay', 'Plettenberg Bay, South Africa', 'Gqeberha', 'Gqeberha, South Africa', 'N2', 'N2 Garden Route east through the Tsitsikamma plaza.', 'unverified', null, null, '{}'::text[], array['iol-2026-routes']::text[], 'published'),
  ('pta-rustenburg-n4', 'Pretoria → Rustenburg', 'Pretoria', 'Pretoria, South Africa', 'Rustenburg', 'Rustenburg, South Africa', 'N4', 'N1 north to the Doornpoort interchange, then the N4 Platinum Highway west past Brits.', 'unverified', null, null, array['Bakwena''s 2026 tariffs are valid until 28 February 2027.', 'Routes avoiding the Platinum Highway (for example via Hartbeespoort) pass different plazas or none.']::text[], array['wikipedia-platinum-highway', 'bakwena-tolls-and-tariffs']::text[], 'published'),
  ('dbn-richards-bay-n2', 'Durban → Richards Bay', 'Durban', 'Durban, South Africa', 'Richards Bay', 'Richards Bay, South Africa', 'N2', 'N2 North Coast through oThongathi, Mvoti and Mtunzini.', 'unverified', null, null, array['The Mtunzini south ramp plaza applies only if you join or leave the N2 there.']::text[], array['foresight-n2-2026', 'sanral-sst-locations']::text[], 'published');
