insert into public.notices (id, title, body, severity, show_from, show_until, source_ids) values
  ('tariffs-2026-unverified', '2026 tariffs: not yet checked against the Gazette', 'Toll tariffs were adjusted on 1 March 2026 (SANRAL +3.12%, Government Gazette Nos. 54087 and 54088). Every price in Toll-E matches SANRAL''s official 2026 tariff publication and the TRAC and Bakwena tariff pages. A person has not yet checked them against the Gazette itself, so they are still marked Unverified. The amount shown at the plaza is what you pay.', 'warning', '2026-03-01', null, array['sanral-tariffs-2026-poster', 'sanews-2026-toll-increase']::text[]),
  ('n3-tariffs-under-review', 'N3 tariffs under review', 'N3 Toll Concession''s website and SANRAL''s 2026 tariff poster show different N3 tariffs. Toll-E shows the poster figures and marks every N3TC plaza as under review until the Gazette is checked.', 'warning', '2026-03-01', '2026-10-22', array['n3tc-toll-tariffs', 'sanral-tariffs-2026-poster']::text[]),
  ('gauteng-etolls-ended', 'Gauteng e-tolls have ended', 'E-toll gantries on Gauteng freeways were switched off at midnight on 11 April 2024, so Toll-E includes no e-toll charges. In June 2026 Cabinet approved writing off historical e-toll debt; amounts already paid are not refunded.', 'info', '2024-04-11', null, array['sanral-etoll-end-information-pack', 'engineeringnews-etoll-debt-2026']::text[]),
  ('contactless-card-payments', 'Card payments are now tap-to-pay', 'News reports say SANRAL plazas stopped accepting magstripe (swipe) cards from 1 December 2025 in favour of contactless bank cards and mobile wallets. American Express, Diners Club and RCS cards are reported as not accepted. Cash and SANRAL tags remain accepted.', 'info', '2025-12-01', null, array['pretorianews-tap-to-pay', 'businesstech-toll-payments']::text[]);
insert into public.dataset_meta (key, value) values ('dataset_version', '2026-10-23.1')
